// Generate report narrative
const decisions = $input.all();

const tickerGroups = {};
for (const d of decisions) {
  const ticker = d.json.ticker;
  if (!tickerGroups[ticker]) tickerGroups[ticker] = [];
  tickerGroups[ticker].push(d.json);
}

const decisionGroups = Object.entries(tickerGroups).map(([ticker, decs]) => ({
  ticker,
  decision_ids: decs.map(d => d.decision_id),
  narrative_tr: `${ticker} için ${decs.length} karar alındı.`
}));

return [{
  json: {
    report_type: 'MORNING_BRIEFING',
    period_start: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
    period_end: new Date().toISOString(),
    portfolio_id: 'default',
    executive_summary_tr: `${decisions.length} karar analiz edildi.`,
    decisions_count: decisions.length,
    decision_groups: decisionGroups,
    action_items_tr: ['Piyasayı izlemeye devam edin.'],
    word_count: decisions.length * 10
  }
}];
